import * as React from "react";
import {Icon,type IconProps} from "@/components/ui/icon";

export type BookMarkedIconProps=Omit<IconProps,"name">;
/** Lucide "book-marked" through the Cojeev Icon: motion presets, sizes and feedback included. */
export function BookMarkedIcon(props:BookMarkedIconProps){return <Icon name="book-marked" {...props}/>;}
